  html body.task-mode.desktop-sidebar-v158:not(.desktop-sidebar-pinned) .app-shell.detail-open .quick-add button,
  html body.task-mode.desktop-sidebar-v158:not(.desktop-sidebar-pinned) .app-shell.detail-open #quickAddButton {
    width: 88px !important;
    min-width: 88px !important;
    max-width: 88px !important;
    padding-left: 6px !important;
    padding-right: 6px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
  }
}

